package example

// Sockets names the two socket tokens this specimen tree writes.
//
// The first spelling stands inside a longer lowercase word, so the site
// walk reads no occurrence of it and a substitution keyed to it reaches
// nothing. The second stands on token boundaries and is one site.
var Sockets = []string{
	"sample-tokens",
	"stray-token",
}
